import type { Spec, Property } from "./spec";

export function generateTests(spec: Spec): string {
  const header = `import { test, expect } from "vitest";
import * as fc from "fast-check";

// Generated by GhostSpec from spec: ${spec.name}
`;
  const body = spec.properties.map((p) => renderProperty(p)).join("\n");
  return header + body;
}

function renderProperty(p: Property): string {
  switch (p.kind) {
    case "no-crash":
      return `test("${p.name} does not crash", () => {
  fc.assert(fc.property(fc.anything(), (x) => {
    // input: ${p.input}
    return true;
  }));
});\n`;
    default:
      return `test("${p.name}", () => {
  // property: ${p.name}(${p.input}) -> ${p.expected ?? "true"}
  expect(true).toBe(true);
});\n`;
  }
}